class GreetingWidget {
  final String name;

  const GreetingWidget(this.name);

  String build() {
    return 'Widget: GreetingWidget, Name: $name';
  }
}

void main() {
  final alice = GreetingWidget('Alice');
  final binh = GreetingWidget('Bình');

  print(alice.build());
  print(binh.build());
}

class WidgetNode {
  final String type;
  final List<WidgetNode> children;

  WidgetNode(this.type, {List<WidgetNode>? children})
      : children = children ?? [];

  void addChild(WidgetNode child) {
    children.add(child);
  }

  String describe() {
    return '$type(${children.length})';
  }
}

void main() {
  final root = WidgetNode('Scaffold');
  final column = WidgetNode('Column');

  column.addChild(WidgetNode('Text'));
  column.addChild(WidgetNode('Button'));
  root.addChild(column);
  root.addChild(WidgetNode('AppBar'));

  print('Root: ${root.describe()}');
  print('Column: ${column.describe()}');
  print('Column con trực tiếp: ${column.children.length}');
}

class Counter {
  int _count = 0;

  void increment() {
    _count++;
  }

  int getCount() {
    return _count;
  }

  String build() {
    return 'Count: $_count';
  }
}

void main() {
  final counter = Counter();
  print('Ban đầu: ${counter.build()}');

  counter.increment();
  counter.increment();
  counter.increment();

  print('Sau 3 lần increment: ${counter.build()}');
  print('getCount() = ${counter.getCount()}');
}

