class WidgetNode {
  final String type;
  final List<WidgetNode> children;

  WidgetNode(this.type, {List<WidgetNode>? children})
      : children = children ?? [];

  void addChild(WidgetNode child) {
    children.add(child);
  }

  String describe() {
    return '$type(${children.length})';
  }

  bool find(String type) {
    for (final child in children) {
      if (child.type == type || child.find(type)) {
        return true;
      }
    }
    return false;
  }
}

void main() {
  final root = WidgetNode('Scaffold');
  final column = WidgetNode('Column');
  column.addChild(WidgetNode('Text'));
  column.addChild(WidgetNode('Button'));
  root.addChild(column);
  root.addChild(WidgetNode('AppBar'));

  print(root.describe());
  print('Has Column: ${root.find('Column')}');
  print('Has Text: ${root.find('Text')}');
  print('Has Row: ${root.find('Row')}');
}
